cards.solution:
status = input().strip().lower()
sisa = int(input())
if status == "selesai":
    print("Selesai")
elif sisa < 0:
    print("Terlambat")
elif sisa == 0:
    print("Hari ini")
elif sisa <= 2:
    print("Segera")
else:
    print("Santai")

